<?php
/** Real Study/Native composition with the participant input/output boundaries. */
define('DOING_CRON',true);define('EIPSI_STUDY_ENGINE_KEYRING',array('current'=>'HTTP_TEST','keys'=>array('HTTP_TEST'=>str_repeat('6b',32))));define('EIPSI_STUDY_ENGINE_ACCESS_KEYRING',array('current'=>'ACCESS_TEST','keys'=>array('ACCESS_TEST'=>str_repeat('61',32))));
require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';require __DIR__.'/study-engine/cross-sectional/support.php';require __DIR__.'/study-engine/persistence/support.php';require __DIR__.'/study-engine/longitudinal/support.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/runtime/NativeBridge.php';
use EIPSI\AssessmentEditor\Runtime as N;use EIPSI\StudyEngine\Longitudinal as L;use EIPSI\StudyEngine\Runtime as R;
$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z');$cases=array();$c3l_studies=array();$failed=0;$priorCron=_get_cron_array();wp_set_current_user(1);
function c3l_owner(){return new N\Owner(null,static fn()=>strtotime($GLOBALS['pf_now']));}
function c3l_native($p,$f){$_COOKIE[L\Identity::cookieName($p['public'])]=$f['token'];return R\NativeBridge::offer($f);}
require __DIR__.'/sec3/logical-support.php';
function c3l_frame($id){return N\EffectiveAssessmentProjection::frame(c3l_owner()->view($id));}
function c3l_request($f,$action,$answers=array()){$metadata=$f['session']['metadata']??array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$f['definition']['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);if($f['randomization']!==null)$metadata['randomization']=$f['randomization'];return array('action'=>$action,'command_id'=>'SEC3_LOGIC_'.bin2hex(random_bytes(8)),'revision'=>$f['revision'],'version_id'=>$f['version_id'],'csrf'=>$f['csrf'],'answers'=>$answers,'touched'=>array(),'metadata'=>$metadata);}
function c3l_send($f,$action,$answers=array()){return N\EffectiveAssessmentProjection::frame(c3l_owner()->command($f['execution_id'],c3l_request($f,$action,$answers),true));}
$cases['Intra condition delivers only its authorized question and keeps entry boundary']=function(){list($p,$f,$id)=c3l_logic('GO_QUESTION');$first=c3l_frame($id);pe_assert(strpos(json_encode($first),'TARGET_Q')===false,'Future Assessment leaked');$r=c3l_send($first,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['execution_id']===$id&&$r['page']===1&&$r['logical_entry_page']===1,'Server condition changed');$body=json_encode($r['definition']);pe_assert(strpos($body,'SOURCE_Q1')!==false&&strpos($body,'SOURCE_Q0')===false,'Wrong entry projection');};
$cases['Cross Assessment Jump delivers destination only after server transition']=function(){list($p,$f,$id)=c3l_logic('JUMP');$first=c3l_frame($id);pe_assert(strpos(json_encode($first),'TARGET_Q')===false);$r=c3l_send($first,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['execution_id']!==$id&&$r['page']===1);$body=json_encode($r['definition']);pe_assert(strpos($body,'TARGET_Q1')!==false&&strpos($body,'TARGET_Q0')===false,'Jump disclosed prefix');$source=c3l_owner()->store->find('executions',$id);pe_assert($source['state']==='LOGICAL_EXIT'&&json_decode($source['final_json'],true)['answers']['SOURCE_R0']==='go','Source answer lost');};
$cases['Wait keeps future Assessment content and target identity out of participant payload']=function(){list($p,$f,$id)=c3l_logic('WAIT',true);$first=c3l_frame($id);$r=c3l_send($first,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['state']==='LOGICAL_EXIT');pe_assert(strpos(json_encode($r),'TARGET_Q')===false&&strpos(json_encode($r),'E_SEC2_TARGET')===false,'Wait disclosed future destination');$count=c3l_owner()->store->db->row(c3l_owner()->store->prepare('SELECT COUNT(*) AS n FROM '.c3l_owner()->store->table('executions').' WHERE management_execution=%s',$f['access']['execution_id']));pe_assert((int)$count['n']===1,'Wait created target Native');};
$cases['Forged Jump and forced outcome cannot mutate scientific state']=function(){list($p,$f,$id)=c3l_logic('JUMP');$first=c3l_frame($id);$store=c3l_owner()->store;$before=$store->find('executions',$id);$request=c3l_request($first,'logic',array('SOURCE_R0'=>'go'));$request['jump_target']='E_SEC2_TARGET';try{c3l_owner()->command($id,$request,true);throw new RuntimeException('Forgery accepted');}catch(InvalidArgumentException$e){}pe_equal($before,$store->find('executions',$id),'Forged target changed Native');$request=c3l_request($first,'logic',array('SOURCE_R0'=>'go'));$request['metadata']['randomization']['forced_outcome']='TARGET_Q1';try{c3l_owner()->command($id,$request,true);throw new RuntimeException('Forced outcome accepted');}catch(RuntimeException$e){pe_assert($e->getCode()===409,'Wrong rejection '.$e->getMessage());}pe_equal($before,$store->find('executions',$id),'Failed provenance mutated source');};
$cases['Same-page logical entry changes projection reference without exposing hidden targets']=function(){list($p,$f,$id)=c3l_logic('GO_QUESTION',false,true);$first=c3l_frame($id);$r=c3l_send($first,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['page']===0&&$r['projection_ref']!==$first['projection_ref'],'Projection did not signal same-page logical change');$body=json_encode($r['definition']);pe_assert(strpos($body,'SOURCE_Q1')!==false&&strpos($body,'SOURCE_Q0')===false);};
try{foreach($cases as$name=>$fn){try{$fn();echo'PASS '.$name."\n";}catch(Throwable$e){$failed++;echo'FAIL '.$name.': '.$e->getMessage()."\n";}}}finally{_set_cron_array($priorCron);}
echo count($cases).' tests, '.$failed." failures\n";ob_end_flush();exit($failed?1:0);
